-- SQL Script to insert subtopics from Fundamentos de circuitos elétricos dataset

-- Insert Subtopics
INSERT INTO prompts (id, subtopic_id, subject, prompt, system, messages, reference_documents, version, number_questions) VALUES

-- Topic 1
-- Subtopic 1
(1, 1, 'Definições Básicas', 'Gera uma questão de escolha múltipla em português sobre definições básicas da terminologia de circuitos elétricos. A pergunta deve testar o significado de termos como nó, ramo, malha, corrente e tensão, sem depender de um documento de apoio.', NULL, NULL, NULL, 1, 0),
(2, 1, 'Associação de Termos', 'Gera uma questão de escolha múltipla em português em que o aluno tenha de associar corretamente um termo de circuitos elétricos à respetiva definição. Usa linguagem simples e foca a terminologia essencial da análise de circuitos.', NULL, NULL, NULL, 1, 0),
(3, 1, 'Termo Correto', 'Gera uma questão de escolha múltipla em português que peça para identificar qual o termo técnico correto para descrever uma ligação, um percurso fechado ou uma grandeza elétrica. Evita cálculos e foca apenas a nomenclatura.', NULL, NULL, NULL, 1, 0),
(4, 1, 'Linguagem Técnica', 'Gera uma questão de escolha múltipla em português sobre a linguagem técnica usada em circuitos elétricos. A pergunta deve distinguir entre termos semelhantes e mostrar a diferença entre eles de forma conceptual.', NULL, NULL, NULL, 1, 0),
-- Subtopic 2
(5, 2, 'Soma Algébrica das Tensões', 'Gera uma questão de escolha múltipla em português sobre a Lei de Kirchhoff das Malhas, focando a ideia de soma algébrica das tensões num percurso fechado. Não uses cálculos numéricos; testa apenas o conceito.', NULL, NULL, NULL, 1, 0),
(6, 2, 'Condição de Percurso Fechado', 'Gera uma questão de escolha múltipla em português que peça ao aluno para reconhecer quando a Lei de Kirchhoff das Malhas se aplica. A pergunta deve relacionar a lei com um percurso fechado no circuito.', NULL, NULL, NULL, 1, 0),
(7, 2, 'Interpretação da KVL', 'Gera uma questão de escolha múltipla em português sobre a interpretação física da Lei de Kirchhoff das Malhas. A pergunta deve avaliar se o aluno entende que as subidas e quedas de tensão se equilibram numa malha.', NULL, NULL, NULL, 1, 0),
(8, 2, 'Identificação de Afirmação Correta', 'Gera uma questão de escolha múltipla em português em que o aluno deva escolher a afirmação correta sobre a Lei de Kirchhoff das Malhas. Inclui distratores conceptuais plausíveis e mantém a questão curta.', NULL, NULL, NULL, 1, 0),
-- Subtopic 3
(9, 3, 'Ordem dos Passos', 'Gera uma questão de escolha múltipla em português sobre a ordem correta dos passos do método das correntes nas malhas. A pergunta deve exigir que o aluno reconheça a sequência lógica do procedimento.', NULL, NULL, NULL, 1, 0),
(10, 3, 'Passo Seguinte', 'Gera uma questão de escolha múltipla em português que peça ao aluno para identificar qual é o próximo passo do método depois de selecionar as malhas e definir os sentidos das correntes.', NULL, NULL, NULL, 1, 0),
(11, 3, 'Etapa em Falta', 'Gera uma questão de escolha múltipla em português em que uma sequência do método aparece incompleta e o aluno tem de escolher o passo em falta. Foca a lógica sequencial e não o cálculo.', NULL, NULL, NULL, 1, 0),
(12, 3, 'Encadeamento Lógico', 'Gera uma questão de escolha múltipla em português sobre o encadeamento lógico dos passos do método por correntes de malha, desde a leitura do circuito até à interpretação final dos resultados.', NULL, NULL, NULL, 1, 0),
-- Subtopic 4
(13, 4, 'Fonte Entre Malhas', 'Gera uma questão de escolha múltipla em português sobre o tratamento de uma fonte de corrente colocada entre duas malhas. A pergunta deve avaliar o conceito de supermalha ou de restrição de corrente, sem cálculo numérico.', NULL, NULL, NULL, 1, 0),
(14, 4, 'Restrição de Corrente', 'Gera uma questão de escolha múltipla em português que peça ao aluno para identificar a consequência de uma fonte de corrente num ramo partilhado por malhas. Foca a restrição imposta pela fonte.', NULL, NULL, NULL, 1, 0),
(15, 4, 'Supermalha', 'Gera uma questão de escolha múltipla em português sobre o conceito de supermalha. A pergunta deve testar se o aluno sabe quando é necessário contornar uma fonte de corrente entre malhas.', NULL, NULL, NULL, 1, 0),
(16, 4, 'Fonte no Contorno', 'Gera uma questão de escolha múltipla em português sobre como tratar uma fonte de corrente localizada no contorno de uma malha. A questão deve ser conceptual e clara.', NULL, NULL, NULL, 1, 0),
-- Subtopic 5
(17, 5, 'Ramo Partilhado', 'Gera uma questão de escolha múltipla em português sobre a relação entre corrente de malha e corrente num ramo partilhado. A pergunta deve avaliar se o aluno entende que a corrente do ramo pode resultar da diferença entre malhas.', NULL, NULL, NULL, 1, 0),
(18, 5, 'Expressão da Corrente', 'Gera uma questão de escolha múltipla em português que peça ao aluno para identificar a expressão correta da corrente num ramo a partir das correntes de malha envolvidas. Não uses números, apenas relações conceptuais.', NULL, NULL, NULL, 1, 0),
(19, 5, 'Corrente de Ramo vs. Corrente de Malha', 'Gera uma questão de escolha múltipla em português que compare corrente de ramo e corrente de malha. O aluno deve reconhecer quando os valores coincidem e quando precisam de ser combinados.', NULL, NULL, NULL, 1, 0),
(20, 5, 'Componentes Partilhados', 'Gera uma questão de escolha múltipla em português sobre componentes partilhados entre malhas e a forma como isso altera a corrente no ramo. A questão deve ser conceptual e direta.', NULL, NULL, NULL, 1, 0),
-- Subtopic 6
(21, 6, 'Sentido Assumido', 'Gera uma questão de escolha múltipla em português sobre a interpretação do sentido assumido para uma corrente. A pergunta deve focar a convenção de sinais e o significado do resultado positivo ou negativo.', NULL, NULL, NULL, 1, 0),
(22, 6, 'Resultado Negativo', 'Gera uma questão de escolha múltipla em português que peça ao aluno para interpretar o que significa uma corrente calculada com valor negativo. A questão deve ser conceptual e não numérica.', NULL, NULL, NULL, 1, 0),
(23, 6, 'Direções Opostas', 'Gera uma questão de escolha múltipla em português sobre correntes com sentidos opostos. O aluno deve reconhecer como o sentido escolhido inicialmente influencia a leitura do resultado.', NULL, NULL, NULL, 1, 0),
(24, 6, 'Leitura Física do Sinal', 'Gera uma questão de escolha múltipla em português sobre a leitura física do sinal de uma corrente em circuitos. A pergunta deve ajudar a interpretar a direção real da corrente em relação ao sentido de referência.', NULL, NULL, NULL, 1, 0),

-- Topic 2
-- Topic 7
(25, 7, 'Número de Nós', 'Mostra o esquemático do circuito e pede ao aluno para identificar o número total de nós elétricos distintos existentes no circuito.', NULL, NULL, NULL, 1, 0),
(26, 7, 'Número de Ramos', 'Mostra o circuito e pergunta quantos ramos elétricos existem, considerando cada ligação entre dois nós como um ramo.', NULL, NULL, NULL, 1, 0),
(27, 7, 'Identificação de Componentes em Paralelo', 'Apresenta o circuito e pede ao aluno para identificar quais componentes estão ligados em paralelo, ou seja, entre os mesmos dois nós.', NULL, NULL, NULL, 1, 0),
(28, 7, 'Identificação de Ramos Paralelos', 'Mostra os ramos do circuito e pede ao aluno para identificar quais ramos estão ligados em paralelo. Os ramos que estão em paralelo compartilham Nós de incidência que podem ser conferidos na tabela dos ramos.', NULL, NULL, NULL, 1, 0),
(29, 7, 'Número de Malhas Principais / Número de Equações de Malha', 'Pede ao aluno para calcular o número de malhas principais do circuito com base na fórmula e no circuito apresentado.', NULL, NULL, NULL, 1, 0),
(30, 7, 'Número de Malhas Auxiliares / Fontes de Corrente Ideais', 'Mostra o circuito e pede ao aluno para determinar quantas malhas auxiliares existem associadas às fontes de corrente ideais.', NULL, NULL, NULL, 1, 0),
(31, 7, 'Leitura da Estrutura do Circuito', 'Apresenta o esquemático do circuito e pede ao aluno para identificar se os componentes estão ligados em série, em paralelo ou numa configuração mista.', NULL, NULL, NULL, 1, 0),
(32, 7, 'Identificação de Componentes Ligados ao Mesmo Nó', 'Mostra um nó do circuito e pede ao aluno para identificar quais componentes partilham esse nó em comum.', NULL, NULL, NULL, 1, 0),
(33, 7, 'Reconhecimento de Ligações Diretas', 'Apresenta o circuito e pede ao aluno para identificar quais componentes estão diretamente ligados entre si sem elementos intermédios.', NULL, NULL, NULL, 1, 0),
(34, 7, 'Identificação de Componentes Exclusivos de um Ramo', 'Apresenta a lista de ramos do circuito e pede ao aluno para identificar quais componentes pertencem exclusivamente a um único ramo.', NULL, NULL, NULL, 1, 0),
(35, 7, 'Interpretação da Tabela de Componentes', 'Mostra a tabela de componentes do circuito e pede ao aluno para interpretar os tipos de componentes presentes e respetivos valores nominais.', NULL, NULL, NULL, 1, 0),
-- Topic 8
(36, 8, 'Identificação de Componentes da Malha', 'Mostra a figura de uma malha específica e pede ao aluno para identificar todos os componentes pertencentes a essa malha.', NULL, NULL, NULL, 1, 0),
(37, 8, 'Identificação de Ramos da Malha', 'Apresenta o esquemático de uma malha e pede ao aluno para indicar quais os ramos que fazem parte dessa malha.', NULL, NULL, NULL, 1, 0),
(38, 8, 'Número de Componentes da Malha', 'Mostra uma malha do circuito e pede ao aluno para indicar quantos componentes existem nessa malha.', NULL, NULL, NULL, 1, 0),
(39, 8, 'Número de Ramos da Malha', 'Apresenta uma malha específica e pergunta quantos ramos pertencem à malha.', NULL, NULL, NULL, 1, 0),
(40, 8, 'Malha Principal', 'Mostra uma malha específica e pergunta ao aluno se essa malha pode ser considerada uma malha principal no contexto da análise por correntes de malha.', NULL, NULL, NULL, 1, 0),
(41, 8, 'Malha Auxiliar', 'Apresenta uma malha e pede ao aluno para indicar se essa malha deve ser tratada como uma malha auxiliar.', NULL, NULL, NULL, 1, 0),
(42, 8, 'Validação de Malha', 'Mostra um conjunto de ramos destacados no circuito e pergunta ao aluno se o percurso apresentado constitui uma malha válida.', NULL, NULL, NULL, 1, 0),
