(50, 8, 'Seleção de Conjunto Válido de Malhas', 'Apresenta vários conjuntos possíveis de malhas e pede ao aluno para selecionar o conjunto adequado para realizar a análise por correntes de malha.', NULL, NULL, NULL, 1, 0),
