(56, 8, 'Identificação de Percurso Fechado', 'Mostra um percurso destacado no circuito e pede ao aluno para indicar se esse percurso constitui um caminho fechado válido para análise de malha.', NULL, NULL, NULL, 1, 0),
(57, 8, 'Deteção de Percurso Não Válido', 'Apresenta um conjunto de ramos destacados e pede ao aluno para identificar porque razão o percurso não constitui uma malha válida.', NULL, NULL, NULL, 1, 0),
