(72, 9, 'Validação de Equação KVL', 'Mostra uma equação proposta para uma malha e pede ao aluno para indicar se a equação está correta.', NULL, NULL, NULL, 1, 0),
(73, 9, 'Número de Equações Necessárias', 'Mostra o circuito e pergunta quantas equações independentes são necessárias para resolver o sistema por correntes de malha.', NULL, NULL, NULL, 1, 0),
